uint8_t *fr_inet_ifid_pton(uint8_t out[static 8], char const *ifid_str)
{
        static char const xdigits[] = "0123456789abcdef";
        char const *p, *pch;
        int num_id = 0, val = 0, idx = 0;

        for (p = ifid_str; ; ++p) {
                if (*p == ':' || *p == '\0') {
                        if (num_id <= 0)
                                return NULL;

                        /*
                         *      Drop 'val' into the array.
                         */
                        out[idx] = (val >> 8) & 0xff;
                        out[idx + 1] = val & 0xff;
                        if (*p == '\0') {
                                /*
                                 *      Must have all entries before
                                 *      end of the string.
                                 */
                                if (idx != 6)
                                        return NULL;
                                break;
                        }
                        val = 0;
                        num_id = 0;
                        if ((idx += 2) > 6)
                                return NULL;
                } else if ((pch = strchr(xdigits, tolower(*p))) != NULL) {
                        if (++num_id > 4)
                                return NULL;
                        /*
                         *      Dumb version of 'scanf'
                         */
                        val <<= 4;
                        val |= (pch - xdigits);
                } else
                        return NULL;
        }
        return out;
}

